#include <memory>
#include <string>
#include <utility>

TEST("last in, first out") {
  Stack<int> s;
  s.push(1);
  s.push(2);
  s.push(3);
  CHECK_EQ(s.pop(), 3);
  CHECK_EQ(s.pop(), 2);
  CHECK_EQ(s.size(), std::size_t{1});
}

TEST("works with strings and lvalues") {
  Stack<std::string> s;
  std::string word = "hello";
  s.push(word);
  CHECK_EQ(word, std::string("hello"));  // pushing an lvalue copies; the original is untouched
  CHECK_EQ(s.pop(), std::string("hello"));
  CHECK(s.empty());
}

TEST("top returns a reference you can modify") {
  Stack<int> s;
  s.push(1);
  s.top() = 42;
  CHECK_EQ(s.pop(), 42);
  Stack<int> t;
  t.push(7);
  const Stack<int>& ct = t;
  CHECK_EQ(ct.top(), 7);
}

TEST("works with move-only types") {
  Stack<std::unique_ptr<int>> s;
  s.push(std::make_unique<int>(5));
  auto p = std::make_unique<int>(6);
  s.push(std::move(p));
  CHECK(p == nullptr);
  auto out = s.pop();
  CHECK_EQ(*out, 6);
  CHECK_EQ(*s.top(), 5);
}

TEST("emplace constructs in place") {
  Stack<std::pair<int, std::string>> s;
  auto& ref = s.emplace(1, "one");
  CHECK_EQ(ref.second, std::string("one"));
  CHECK_EQ(s.top().first, 1);
}

TEST("pop and top on an empty stack throw out_of_range") {
  Stack<int> s;
  CHECK_THROWS(s.pop(), std::out_of_range);
  CHECK_THROWS(s.top(), std::out_of_range);
  const Stack<int>& cs = s;
  CHECK_THROWS(cs.top(), std::out_of_range);
}

