#include <cstddef>
#include <stdexcept>
#include <utility>
#include <vector>

template <typename T>
class Stack {
 public:
  void push(const T& value) { items_.push_back(value); }
  void push(T&& value) { items_.push_back(std::move(value)); }

  template <typename... Args>
  T& emplace(Args&&... args) {
    return items_.emplace_back(std::forward<Args>(args)...);
  }

  T pop() {
    if (items_.empty()) throw std::out_of_range("pop from an empty Stack");
    T value = std::move(items_.back());  // move out: works for move-only T, cheap for big T
    items_.pop_back();
    return value;
  }

  T& top() {
    if (items_.empty()) throw std::out_of_range("top of an empty Stack");
    return items_.back();
  }

  const T& top() const {
    if (items_.empty()) throw std::out_of_range("top of an empty Stack");
    return items_.back();
  }

  std::size_t size() const { return items_.size(); }
  bool empty() const { return items_.empty(); }

 private:
  std::vector<T> items_;
};
